-- Notes-inbox items are private to their uploader until filed (admins see all)
create policy "Own intakes" on note_intakes
  for all using ((select is_team_member()) and (created_by = (select current_member_id()) or (select is_admin())))
  with check ((select is_team_member()) and (created_by = (select current_member_id()) or (select is_admin())));
create policy "Own intake files" on note_intake_files
  for all using (exists (
    select 1 from note_intakes i
    where i.id = intake_id and (select is_team_member()) and (i.created_by = (select current_member_id()) or (select is_admin()))
  ))
  with check (exists (
    select 1 from note_intakes i
    where i.id = intake_id and (select is_team_member()) and (i.created_by = (select current_member_id()) or (select is_admin()))
  ));

-- Ticket comments: everyone reads, authors write their own
create policy "Members read comments" on ticket_comments
  for select using ((select is_team_member()));
create policy "Authors insert own comments" on ticket_comments
  for insert with check ((select is_team_member()) and author_id = (select current_member_id()));
create policy "Authors update own comments" on ticket_comments
  for update using (author_id = (select current_member_id())) with check (author_id = (select current_member_id()));
create policy "Authors delete own comments" on ticket_comments
  for delete using (author_id = (select current_member_id()));

-- Meetings are co-edited live
alter publication supabase_realtime add table meetings;

-- ==========================================================================
-- supabase/migrations/0003_fundraising.sql
-- ==========================================================================

-- 0003: Fundraising: contributions and IRS acknowledgement letters, stock
-- gifts and price cache, and donation inquiries.

create table contributions (
  id uuid primary key default gen_random_uuid(),
  contact_id uuid not null references contacts (id),
  -- Null only for in-kind gifts: the organization describes the property but
  -- never asserts a value (IRS Pub 1771: valuation is the donor's job).
  -- For stock gifts this is the internal fair-market value.
  amount_cents bigint check (amount_cents >= 0),
  received_date date not null,
  method text not null
    check (method in ('check', 'ach', 'wire', 'credit_card', 'stock', 'crypto', 'in_kind')),
  vehicle text not null default 'direct'
    check (vehicle in ('direct', 'daf', 'private_foundation', 'ira_qcd', 'employer_match', 'charitable_trust', 'other')),
  vehicle_sponsor_name text,         -- e.g. the DAF sponsor
  in_kind_description text,
  restriction text not null default 'unrestricted'
    check (restriction in ('unrestricted', 'donor_restricted')),
  restriction_purpose text,
  quid_pro_quo boolean not null default false,
  goods_services_description text,
  goods_services_value_cents bigint check (goods_services_value_cents >= 0),
  check_number text,
  notes text,
  qbo_txn_type text,
  qbo_txn_id text,
  entered_by uuid references team_members (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint in_kind_requires_description check (method <> 'in_kind' or in_kind_description is not null),
  constraint cash_requires_amount check (method = 'in_kind' or amount_cents is not null),
  constraint quid_pro_quo_requires_details check (
    not quid_pro_quo or (goods_services_description is not null and goods_services_value_cents is not null)
  ),
  -- DAF and QCD gifts can't carry benefits back to the donor
  constraint vehicle_no_quid_pro_quo check (not quid_pro_quo or vehicle not in ('daf', 'ira_qcd'))
);

create index contributions_contact_idx on contributions (contact_id);
create index contributions_date_idx on contributions (received_date);

create table acknowledgement_letters (
  id uuid primary key default gen_random_uuid(),
  contribution_id uuid not null unique references contributions (id) on delete cascade,
  status text not null default 'draft' check (status in ('draft', 'generated', 'sent')),
  pdf_storage_path text,
  -- Frozen copy of the data the letter was rendered from, so later edits to
  -- the contribution or settings never silently change a sent letter
  body_snapshot jsonb,
  sent_to_email text,
  sent_at timestamptz,
  resend_message_id text,
  generated_by uuid references team_members (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table stock_contribution_details (
  contribution_id uuid primary key references contributions (id) on delete cascade,
  security_name text not null,
  ticker_symbol text check (ticker_symbol is null or ticker_symbol = upper(ticker_symbol)),
  cusip text,
  shares numeric(20, 6) not null check (shares > 0),
  valuation_date date not null,
  fmv_per_share_cents numeric(20, 6) check (fmv_per_share_cents >= 0),
  fmv_total_cents bigint not null check (fmv_total_cents >= 0),
  valuation_source text not null default 'manual'
    check (valuation_source in ('manual', 'api_estimate', 'broker_statement')),
  market_price_source text,
  brokerage_account text,
  transfer_received_date date,
  sale_date date,
  sale_gross_cents bigint check (sale_gross_cents >= 0),
  sale_fees_cents bigint check (sale_fees_cents >= 0),
  sale_net_cents bigint check (sale_net_cents >= 0),
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index stock_contribution_ticker_idx on stock_contribution_details (ticker_symbol);
create index stock_contribution_valuation_date_idx on stock_contribution_details (valuation_date);

-- Daily market data cache (optional Financial Modeling Prep integration)
create table security_prices (
  id uuid primary key default gen_random_uuid(),
  symbol text not null check (symbol = upper(symbol)),
  price_date date not null,
  open_cents bigint check (open_cents >= 0),
  high_cents bigint check (high_cents >= 0),
  low_cents bigint check (low_cents >= 0),
  close_cents bigint not null check (close_cents >= 0),
  adjusted_close_cents bigint check (adjusted_close_cents >= 0),
  volume bigint check (volume >= 0),
  source text not null default 'manual',
  fetched_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (symbol, price_date, source)
);

create index security_prices_symbol_date_idx on security_prices (symbol, price_date desc);

-- Gift intentions submitted from the organization's public website
create table donation_inquiries (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  email text not null,
  phone text,
  organization text,
  gift_method text not null default 'other'
    check (gift_method in ('check', 'wire_ach', 'daf', 'stock_crypto', 'other')),
  amount_cents bigint check (amount_cents >= 0),
  amount_text text,
  message text,
  status text not null default 'new' check (status in ('new', 'contacted', 'archived')),
  source text not null default 'website',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index donation_inquiries_status_idx on donation_inquiries (status);
create index donation_inquiries_created_idx on donation_inquiries (created_at desc);

alter table contributions enable row level security;
alter table acknowledgement_letters enable row level security;
alter table stock_contribution_details enable row level security;
alter table security_prices enable row level security;
alter table donation_inquiries enable row level security;

create policy "Members full access" on contributions
  for all using ((select is_team_member())) with check ((select is_team_member()));
create policy "Members full access" on acknowledgement_letters
  for all using ((select is_team_member())) with check ((select is_team_member()));
create policy "Members full access" on stock_contribution_details
  for all using ((select is_team_member())) with check ((select is_team_member()));
create policy "Members full access" on security_prices
  for all using ((select is_team_member())) with check ((select is_team_member()));
create policy "Members full access" on donation_inquiries
  for all using ((select is_team_member())) with check ((select is_team_member()));

-- ==========================================================================
-- supabase/migrations/0004_expenses_and_attachments.sql
-- ==========================================================================

-- 0004: Expense categories (Form 990 functional classes), expenses, and
-- the polymorphic attachments table used across the app.

create table expense_categories (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  functional_class text not null
    check (functional_class in ('program', 'management_general', 'fundraising')),
  form_990_line text,
  -- Categories the app itself relies on (e.g. 'grants_paid', used when a
  -- disbursement is paid). Renaming the category is fine; the key stays.
  system_key text unique,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table expenses (
  id uuid primary key default gen_random_uuid(),
  expense_date date not null,
  amount_cents bigint not null check (amount_cents >= 0),
  description text not null,
  category_id uuid not null references expense_categories (id),
  vendor_contact_id uuid references contacts (id),
  payment_method text check (payment_method in ('card', 'check', 'ach', 'wire', 'reimbursement')),
  status text not null default 'paid' check (status in ('pending', 'paid', 'reimbursed')),
  -- Set when a team member fronted the expense personally
  paid_by uuid references team_members (id) on delete set null,
  is_1099_eligible boolean not null default false,
  -- Set when this expense was created by paying a grant disbursement
  -- (foreign key added in 0005 once disbursements exists)
  disbursement_id uuid,
  notes text,
  -- QuickBooks Online sync. qbo_source says which side owns the record:
  -- 'app' = created here; 'qbo' = created from a QuickBooks transaction.
  qbo_source text not null default 'app' check (qbo_source in ('app', 'qbo')),
  qbo_purchase_id text,
  qbo_sync_status text not null default 'not_synced'
    check (qbo_sync_status in ('not_synced', 'synced', 'failed')),
  qbo_synced_at timestamptz,
  qbo_sync_error text,
  entered_by uuid references team_members (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index expenses_date_idx on expenses (expense_date);
create index expenses_category_idx on expenses (category_id);
create index expenses_vendor_idx on expenses (vendor_contact_id);

-- Files attached to records. Governance documents (bylaws, determination
-- letter, minutes) use entity_type 'governance' with the nil UUID.
create table attachments (
  id uuid primary key default gen_random_uuid(),
  entity_type text not null check (entity_type in (
    'expense', 'contribution', 'grant_proposal', 'grant_out', 'grantee_report',
    'contact', 'governance', 'pri'
  )),
  entity_id uuid not null,
  storage_path text not null,        -- in the documents bucket
  file_name text not null,
  mime_type text,
  size_bytes bigint,
  uploaded_by uuid references team_members (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index attachments_entity_idx on attachments (entity_type, entity_id);

alter table expense_categories enable row level security;
alter table expenses enable row level security;
alter table attachments enable row level security;

create policy "Members read categories" on expense_categories
  for select using ((select is_team_member()));
create policy "Admins manage categories" on expense_categories
  for all using ((select is_admin())) with check ((select is_admin()));

-- Expenses are admin-only (they expose payroll and reimbursements)
create policy "Admins full access" on expenses
  for all using ((select is_admin())) with check ((select is_admin()));

-- Expense attachments follow expense access; everything else is open to
-- the team
create policy "Members access attachments" on attachments
  for all using ((select is_team_member()) and (entity_type <> 'expense' or (select is_admin())))
  with check ((select is_team_member()) and (entity_type <> 'expense' or (select is_admin())));

-- ==========================================================================
-- supabase/migrations/0005_grantmaking.sql
-- ==========================================================================

-- 0005: Grantmaking: proposals (intake → blind review → diligence memo →
-- decision), awards, disbursements and grantee reports.

create table grant_proposals (
  id uuid primary key default gen_random_uuid(),
  -- 'external' = submitted through the public intake endpoint; arrives
  -- with raw applicant fields and no contact until a team member links one.
  -- 'internal' = created by the team; skips review straight to diligence.
  origin text not null default 'internal' check (origin in ('external', 'internal')),
  applicant_contact_id uuid references contacts (id),
  applicant_name text,
  applicant_email text,
  organization_name text,
  raw_submission jsonb,
  title text not null,
  summary text,
  amount_requested_cents bigint check (amount_requested_cents >= 0),
  program_areas text[] not null default '{}',   -- program_areas.slug values
  received_date date,
  entered_date date not null default current_date,
  source text,
  status text not null default 'received'
    check (status in ('received', 'in_review', 'diligence', 'decided', 'withdrawn')),
  -- Blind voting: reviews stay hidden until every active admin has voted
  -- or recused, then this flips and the team advances or declines.
  votes_revealed boolean not null default false,
  decision text check (decision in ('approved', 'declined')),
  decision_date date,
  decision_notes text,
  declined_stage text check (declined_stage in ('review', 'decision')),
  draft_response_email text,
  response_email_sent_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint applicant_identity_present check (applicant_contact_id is not null or applicant_email is not null),
  constraint decided_requires_decision check (status <> 'decided' or decision is not null)
);

-- The pipeline board filters by status and sorts by received date
create index grant_proposals_status_received_idx on grant_proposals (status, received_date desc);
create index grant_proposals_applicant_idx on grant_proposals (applicant_contact_id);

create table proposal_reviews (
  id uuid primary key default gen_random_uuid(),
  proposal_id uuid not null references grant_proposals (id) on delete cascade,
  reviewer_id uuid not null references team_members (id),
  score integer check (score between 1 and 5),
  vote text check (vote in ('yes', 'no', 'maybe')),
  comments text,
  recused boolean not null default false,   -- conflict of interest
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (proposal_id, reviewer_id),
  constraint recused_means_no_vote check (not recused or (score is null and vote is null))
);

create index proposal_reviews_proposal_idx on proposal_reviews (proposal_id);

create table proposal_comments (
  id uuid primary key default gen_random_uuid(),
  proposal_id uuid not null references grant_proposals (id) on delete cascade,
  author_id uuid not null references team_members (id),
  body text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index proposal_comments_proposal_idx on proposal_comments (proposal_id);

-- Grant memorandum written during diligence: ten numbered sections
-- (registry in lib/grants/memo.ts) plus free-text header fields
create table proposal_memos (
  id uuid primary key default gen_random_uuid(),
  proposal_id uuid not null unique references grant_proposals (id) on delete cascade,
  header_purpose text,
  header_structure text,
  header_decision text,
  header_grantee_descriptor text,
  q_summary_recommendation text,
  q_org_background text,
  q_cause_area_fit text,
  q_theory_of_change text,
  q_counterfactual text,
  q_grant_size_structure text,
  q_success_disappointment text,
  q_risks_mitigations text,
  q_legal_compliance text,
  q_monitoring_evaluation text,
  started_by uuid references team_members (id) on delete set null,
  last_edited_by uuid references team_members (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- AI research runs that draft memo sections (a person saving the memo is
-- the approval step; the AI never writes proposal_memos)
create table grant_research (
  id uuid primary key default gen_random_uuid(),
  proposal_id uuid not null references grant_proposals (id) on delete cascade,
  status text not null default 'running' check (status in ('running', 'complete', 'failed')),
  draft jsonb,
  sources jsonb,
  open_questions jsonb,
  error text,
  model text,
  requested_by uuid references team_members (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index grant_research_proposal_idx on grant_research (proposal_id, created_at desc);

-- Rendered memorandum PDF (in the letters bucket), with a frozen snapshot
create table grant_memo_pdfs (
  id uuid primary key default gen_random_uuid(),
  proposal_id uuid not null unique references grant_proposals (id) on delete cascade,
  pdf_storage_path text not null,
  body_snapshot jsonb not null,
  generated_by uuid references team_members (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table grants_out (
  id uuid primary key default gen_random_uuid(),
  proposal_id uuid unique references grant_proposals (id),
  grantee_contact_id uuid not null references contacts (id),
  purpose text,
  amount_awarded_cents bigint not null check (amount_awarded_cents >= 0),
  award_date date,
  restriction text,
  -- Disbursements can't be paid until the grant agreement is signed
  agreement_signed_date date,
  status text not null default 'awarded' check (status in ('awarded', 'active', 'completed', 'terminated')),
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index grants_out_grantee_idx on grants_out (grantee_contact_id);

create table disbursements (
  id uuid primary key default gen_random_uuid(),
  grant_out_id uuid not null references grants_out (id) on delete cascade,
  amount_cents bigint not null check (amount_cents >= 0),
  scheduled_date date,
  paid_date date,
  method text check (method in ('check', 'ach', 'wire')),
  status text not null default 'scheduled' check (status in ('scheduled', 'paid', 'cancelled')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index disbursements_grant_idx on disbursements (grant_out_id);
-- Dashboard agenda (scheduled, by date) and paid-in-period totals
create index disbursements_status_scheduled_idx on disbursements (status, scheduled_date);
create index disbursements_status_paid_idx on disbursements (status, paid_date);

-- Paying a disbursement creates a matching "Grants paid" expense
alter table expenses
  add constraint expenses_disbursement_fk
  foreign key (disbursement_id) references disbursements (id) on delete set null;
-- ...and at most one: a double "Mark paid" can't book the grant twice
create unique index expenses_disbursement_unique on expenses (disbursement_id)
  where disbursement_id is not null;

create table grantee_reports (
  id uuid primary key default gen_random_uuid(),
  grant_out_id uuid not null references grants_out (id) on delete cascade,
  report_type text not null check (report_type in ('progress', 'final', 'financial')),
  due_date date not null,
  received_date date,
  status text not null default 'upcoming' check (status in ('upcoming', 'received', 'overdue', 'waived')),
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index grantee_reports_grant_idx on grantee_reports (grant_out_id);
create index grantee_reports_due_idx on grantee_reports (due_date);

-- Program-area tags must exist in program_areas
create or replace function check_proposal_program_areas()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  perform assert_program_areas(new.program_areas);
  return new;
end;
$$;

create trigger grant_proposals_program_areas
  before insert or update of program_areas on grant_proposals
  for each row execute function check_proposal_program_areas();

alter table grant_proposals enable row level security;
alter table proposal_reviews enable row level security;
alter table proposal_comments enable row level security;
alter table proposal_memos enable row level security;
alter table grant_research enable row level security;
alter table grant_memo_pdfs enable row level security;
alter table grants_out enable row level security;
alter table disbursements enable row level security;
alter table grantee_reports enable row level security;

create policy "Members full access" on grant_proposals
  for all using ((select is_team_member())) with check ((select is_team_member()));
create policy "Members full access" on proposal_memos
  for all using ((select is_team_member())) with check ((select is_team_member()));
create policy "Members full access" on grant_research
  for all using ((select is_team_member())) with check ((select is_team_member()));
create policy "Members full access" on grant_memo_pdfs
  for all using ((select is_team_member())) with check ((select is_team_member()));
-- Awards and disbursements move money. The team reads them and handles the
-- paperwork (agreement date, award status, scheduling and cancelling
-- payments); making awards, deleting them and anything that pays or
-- re-prices a disbursement is for admins. Column-level rules live in
-- 0009_business_rules.sql.
create policy "Members read awards" on grants_out
  for select using ((select is_team_member()));
create policy "Admins create awards" on grants_out
  for insert with check ((select is_admin()));
create policy "Members update awards" on grants_out
  for update using ((select is_team_member())) with check ((select is_team_member()));
create policy "Admins delete awards" on grants_out
  for delete using ((select is_admin()));
create policy "Members read disbursements" on disbursements
  for select using ((select is_team_member()));
create policy "Members schedule disbursements" on disbursements
  for insert with check ((select is_team_member()));
create policy "Members update disbursements" on disbursements
  for update using ((select is_team_member())) with check ((select is_team_member()));
create policy "Admins delete disbursements" on disbursements
  for delete using ((select is_admin()));
create policy "Members full access" on grantee_reports
  for all using ((select is_team_member())) with check ((select is_team_member()));

-- The grant-review voting body, set by org_settings.grant_review_mode:
-- every active team member ('all_members', the default) or only active
-- admins ('admins'). Every voting rule (review policies, the reveal, the
-- pipeline guard in 0009) goes through these, so they can't drift apart.
create or replace function grant_review_mode()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select grant_review_mode from org_settings where id = 1), 'all_members');
$$;

create or replace function is_grant_voter_member(p_member_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from team_members m
    where m.id = p_member_id
      and m.is_active
      and (grant_review_mode() = 'all_members' or m.role = 'admin')
  );
$$;

-- The signed-in user votes on grant proposals
create or replace function is_grant_voter()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select is_grant_voter_member(current_member_id());
$$;

-- Reviews: the voting body (is_grant_voter) writes, each only their own.
-- Reads are blind: a member sees their own review, and everyone's once the
-- proposal's votes are revealed (0009 also freezes reviews after that).
create policy "Members read own or revealed reviews" on proposal_reviews
  for select using (
    (select is_team_member())
    and (
      reviewer_id = (select current_member_id())
      or exists (select 1 from grant_proposals p where p.id = proposal_id and p.votes_revealed)
    )
  );
create policy "Reviewers insert own review" on proposal_reviews
  for insert with check ((select is_grant_voter()) and reviewer_id = (select current_member_id()));
create policy "Reviewers update own review" on proposal_reviews
  for update using (reviewer_id = (select current_member_id()))
  with check ((select is_grant_voter()) and reviewer_id = (select current_member_id()));
create policy "Reviewers delete own review" on proposal_reviews
  for delete using (reviewer_id = (select current_member_id()));

-- Comments: the team reads all; each person writes only their own
create policy "Members read comments" on proposal_comments
  for select using ((select is_team_member()));
create policy "Authors insert own comments" on proposal_comments
  for insert with check (author_id = (select current_member_id()));
create policy "Authors update own comments" on proposal_comments
  for update using (author_id = (select current_member_id())) with check (author_id = (select current_member_id()));
create policy "Authors delete own comments" on proposal_comments
  for delete using (author_id = (select current_member_id()));

-- ==========================================================================
-- supabase/migrations/0006_pris.sql
-- ==========================================================================

-- 0006: Program-related investments (PRIs): mission-aligned investments
-- (SAFE, note, equity, loan) carried as balance-sheet assets (Form 990
-- Part X line 13, Schedule D Part VIII), not grants. Funding never creates
-- an expense. Funding is gated in the app on a complete mission-alignment
-- memo, an attached executed instrument, and (above the threshold in
-- org_settings) a board approval date.

create table pris (
  id uuid primary key default gen_random_uuid(),
  recipient_contact_id uuid not null references contacts (id),
  instrument text not null check (instrument in ('safe', 'convertible_note', 'equity', 'loan', 'other')),
  purpose text,
  amount_cents bigint not null check (amount_cents >= 0),
  investment_date date,
  board_approval_date date,
  funded_date date,
  method text check (method in ('check', 'ach', 'wire')),
  status text not null default 'committed'
    check (status in ('committed', 'funded', 'converted', 'repaid', 'exited', 'written_off')),
  notes text,
  qbo_txn_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint pri_noncommitted_requires_funded_date check (status = 'committed' or funded_date is not null)
);

create index pris_recipient_idx on pris (recipient_contact_id);
create index pris_status_idx on pris (status);

-- Ten-question mission-alignment memo (registry in lib/pris/memo.ts)
create table pri_memos (
  id uuid primary key default gen_random_uuid(),
  pri_id uuid not null unique references pris (id) on delete cascade,
  q_exempt_purpose text,
  q_why_investment text,
  q_income_not_significant text,
  q_use_of_funds text,
  q_key_terms text,
  q_success_outcomes text,
  q_risks text,
  q_exit_plan text,
  q_conflicts text,
  q_monitoring text,
  started_by uuid references team_members (id) on delete set null,
  last_edited_by uuid references team_members (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table pri_research (
  id uuid primary key default gen_random_uuid(),
  pri_id uuid not null references pris (id) on delete cascade,
  status text not null default 'running' check (status in ('running', 'complete', 'failed')),
  draft jsonb,
  sources jsonb,
  open_questions jsonb,
  error text,
  model text,
  requested_by uuid references team_members (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index pri_research_pri_idx on pri_research (pri_id, created_at desc);

-- Rendered memorandum PDF, filed as an attachment under the PRI
create table pri_memo_pdfs (
  id uuid primary key default gen_random_uuid(),
  pri_id uuid not null unique references pris (id) on delete cascade,
  attachment_id uuid references attachments (id) on delete set null,
  pdf_storage_path text not null,
  body_snapshot jsonb not null,
  generated_by uuid references team_members (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table pris enable row level security;
alter table pri_memos enable row level security;
alter table pri_research enable row level security;
alter table pri_memo_pdfs enable row level security;

create policy "Members full access" on pris
  for all using ((select is_team_member())) with check ((select is_team_member()));
create policy "Members full access" on pri_memos
  for all using ((select is_team_member())) with check ((select is_team_member()));
create policy "Members full access" on pri_research
  for all using ((select is_team_member())) with check ((select is_team_member()));
create policy "Members full access" on pri_memo_pdfs
  for all using ((select is_team_member())) with check ((select is_team_member()));

-- ==========================================================================
-- supabase/migrations/0007_quickbooks.sql
-- ==========================================================================

-- 0007: QuickBooks Online integration (optional; enabled by QBO_* env vars).
--
-- Bank feeds in QuickBooks are the source of cash transactions. The app
-- never creates QuickBooks transactions on its own: it fills in matched
-- bank-feed transactions (payee, account, class, receipts), and pulls
-- changed transactions into qbo_inbox for review. See docs/quickbooks.md.

-- OAuth tokens (singleton)
create table qbo_connection (
  id integer primary key default 1 check (id = 1),
  environment text not null check (environment in ('sandbox', 'production')),
  realm_id text not null,
  company_name text,
  access_token text not null,
  refresh_token text not null,
  access_token_expires_at timestamptz not null,
  refresh_token_expires_at timestamptz not null,
  connected_by uuid references team_members (id) on delete set null,
  connected_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Local values → QuickBooks ids: expense categories → accounts, functional
-- classes → Classes, payment methods → paid-from accounts
create table qbo_mappings (
  id uuid primary key default gen_random_uuid(),
  mapping_type text not null check (mapping_type in ('category', 'functional_class', 'payment_method')),
  local_key text not null,
  qbo_id text not null,
  qbo_name text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (mapping_type, local_key)
);

-- Pull settings and last-run status (singleton)
create table qbo_sync_state (
  id integer primary key default 1 check (id = 1),
  pull_enabled boolean not null default false,
  -- Only exact scheduled-disbursement matches are ever auto-applied
  auto_apply_enabled boolean not null default false,
  pull_since date not null default current_date,
  last_cdc_at timestamptz,
  last_run_at timestamptz,
  last_run_status text check (last_run_status in ('ok', 'error')),
  last_run_error text,
  last_run_stats jsonb,
  updated_at timestamptz not null default now()
);

insert into qbo_sync_state (id) values (1);

-- One row per QuickBooks transaction pulled for review at /banking
create table qbo_inbox (
  id uuid primary key default gen_random_uuid(),
  qbo_entity_type text not null check (qbo_entity_type in (
    'Purchase', 'Deposit', 'Transfer', 'JournalEntry', 'Bill', 'BillPayment', 'SalesReceipt'
  )),
  qbo_entity_id text not null,
  kind text not null default 'new' check (kind in ('new', 'changed', 'deleted')),
  -- 'echo' = a transaction this app sent itself
  status text not null default 'pending'
    check (status in ('pending', 'auto_applied', 'approved', 'dismissed', 'echo')),
  raw jsonb not null,
  previous_raw jsonb,
  txn_date date,
  amount_cents bigint,
  direction text check (direction in ('money_in', 'money_out')),
  counterparty_name text,
  qbo_payment_account_id text,
  qbo_line_account_ids text[] not null default '{}',
  qbo_doc_number text,
  qbo_private_note text,
  suggestion jsonb,
  resolution jsonb,
  dismiss_reason text,
  reviewed_by uuid references team_members (id) on delete set null,
  reviewed_at timestamptz,
  expense_id uuid references expenses (id) on delete set null,
  contribution_id uuid references contributions (id) on delete set null,
  disbursement_id uuid references disbursements (id) on delete set null,
  pri_id uuid references pris (id) on delete set null,
  first_seen_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (qbo_entity_type, qbo_entity_id)
);

-- Banking tabs filter by status and sort by transaction date
create index qbo_inbox_status_txn_date_idx on qbo_inbox (status, txn_date desc);
create index qbo_inbox_txn_date_idx on qbo_inbox (txn_date);

alter table qbo_connection enable row level security;
alter table qbo_mappings enable row level security;
alter table qbo_sync_state enable row level security;
alter table qbo_inbox enable row level security;

create policy "Admins full access" on qbo_connection
  for all using ((select is_admin())) with check ((select is_admin()));
create policy "Admins full access" on qbo_mappings
  for all using ((select is_admin())) with check ((select is_admin()));
create policy "Admins full access" on qbo_sync_state
  for all using ((select is_admin())) with check ((select is_admin()));
create policy "Admins full access" on qbo_inbox
  for all using ((select is_admin())) with check ((select is_admin()));

-- ==========================================================================
-- supabase/migrations/0008_storage.sql
-- ==========================================================================

-- 0008: Storage buckets and policies. All buckets are private; the app
-- serves files through short-lived signed URLs.
--
--   documents   attachments: {entity_type}/{entity_id}/{uuid}-{name},
--               bulk invoice uploads under expense-import/
--   letters     generated PDFs (acknowledgement letters, memoranda) and the
--               letter signature image (assets/signature)
--   note-files  notes-inbox uploads: {intake_id}/{uuid}-{name}; filed notes
--               keep pointing at the same objects via note_attachments

-- Size limits sit above the app's own per-upload limits (10 MB attachments,
-- 20 MB invoices and notes-inbox files) so they only stop uploads that go
-- around the app.
--
-- documents: 50 MB, no type allowlist. General attachments accept any
-- file (spreadsheets, Word documents, archives...) and browsers often
-- report an empty or generic type, so a list would break legitimate
-- uploads. Files are only ever served through signed download URLs.
-- letters: 25 MB; generated PDFs plus the PNG/JPEG signature image.
-- note-files: 25 MB; exactly the types lib/note-intake-core/formats.ts
-- accepts (the drop zone uploads with that content type).
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('documents', 'documents', false, 52428800, null),
  ('letters', 'letters', false, 26214400, array['application/pdf', 'image/png', 'image/jpeg']),
  ('note-files', 'note-files', false, 26214400, array[
    'application/pdf',
    'image/jpeg', 'image/png', 'image/webp', 'image/gif',
    'text/plain', 'text/markdown', 'text/csv',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.ms-excel'
  ])
on conflict (id) do nothing;

-- documents: open to the team, except expense receipts and invoice
-- uploads, which follow expense access (admins only). The helper calls are
-- wrapped in (select ...) so Postgres evaluates them once per statement,
-- not once per object.
create policy "documents read" on storage.objects
  for select using (
    bucket_id = 'documents' and (select is_team_member())
    and ((storage.foldername(name))[1] not in ('expense', 'expense-import') or (select is_admin()))
  );
create policy "documents insert" on storage.objects
  for insert with check (
    bucket_id = 'documents' and (select is_team_member())
    and ((storage.foldername(name))[1] not in ('expense', 'expense-import') or (select is_admin()))
  );
create policy "documents update" on storage.objects
  for update using (
    bucket_id = 'documents' and (select is_team_member())
    and ((storage.foldername(name))[1] not in ('expense', 'expense-import') or (select is_admin()))
  );
create policy "documents delete" on storage.objects
  for delete using (
    bucket_id = 'documents' and (select is_team_member())
    and ((storage.foldername(name))[1] not in ('expense', 'expense-import') or (select is_admin()))
  );

-- letters: the team can read; only admins write from a user session (the
-- app generates letters and memoranda with the service role, so a sent
-- letter's PDF and the signature image can't be swapped by other members)
create policy "letters read" on storage.objects
  for select using (bucket_id = 'letters' and (select is_team_member()));
create policy "letters insert" on storage.objects
  for insert with check (bucket_id = 'letters' and (select is_admin()));
create policy "letters update" on storage.objects
  for update using (bucket_id = 'letters' and (select is_admin()));
create policy "letters delete" on storage.objects
  for delete using (bucket_id = 'letters' and (select is_admin()));

-- note-files: an upload belongs to its intake; the uploader (or an admin)
-- can see it while it's in the inbox, and the whole team can see it once
-- it's attached to a filed note
create or replace function note_file_owned(object_name text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from note_intakes i
    where i.id::text = (storage.foldername(object_name))[1]
      and (i.created_by = current_member_id() or is_admin())
  );
$$;

create or replace function note_file_attached(object_name text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from note_attachments a where a.storage_path = object_name);
$$;

create policy "note files read" on storage.objects
  for select using (
    bucket_id = 'note-files' and (select is_team_member())
    and (note_file_owned(name) or note_file_attached(name))
  );
create policy "note files insert" on storage.objects
  for insert with check (bucket_id = 'note-files' and (select is_team_member()) and note_file_owned(name));
create policy "note files delete" on storage.objects
  for delete using (bucket_id = 'note-files' and (select is_team_member()) and note_file_owned(name));

-- ==========================================================================
-- supabase/migrations/0009_business_rules.sql
-- ==========================================================================

-- 0009: Business rules enforced in the database, so they hold for every
-- client (the app, the Supabase API, SQL by a signed-in user), not just the
-- app's own checks. Service-role sessions (cron, public intake, PDF
-- generation) have no auth.uid() and are trusted.

-- Blind grant review --------------------------------------------------------

-- True once every member of the voting body (is_grant_voter_member, set by
-- org_settings.grant_review_mode) has voted or recused on the proposal
create or replace function proposal_votes_in(p_proposal_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from team_members m where is_grant_voter_member(m.id))
    and not exists (
      select 1 from team_members m
      where is_grant_voter_member(m.id)
        and not exists (
          select 1 from proposal_reviews r
          where r.proposal_id = p_proposal_id
            and r.reviewer_id = m.id
            and (r.recused or r.vote is not null)
        )
    );
$$;

-- Who has weighed in on each proposal (never how): powers the "2 of 3
-- votes in" progress while reviews are still hidden
create or replace function proposal_review_progress(p_proposal_ids uuid[])
returns table (proposal_id uuid, reviewer_id uuid)
language sql
stable
security definer
set search_path = public
as $$
  select r.proposal_id, r.reviewer_id
  from proposal_reviews r
  where is_team_member()
    and r.proposal_id = any (p_proposal_ids)
    and (r.recused or r.vote is not null);
$$;

-- Reveal automatically when the last voter weighs in. Runs inside the
-- reviewer's session, so it raises a transaction-local flag that tells
-- guard_proposal_changes this update is the reveal itself; the guard still
-- re-checks that every voter has weighed in.
create or replace function reveal_votes_when_complete()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if proposal_votes_in(new.proposal_id) then
    perform set_config('app.revealing_votes', 'on', true);
    update grant_proposals
    set votes_revealed = true
    where id = new.proposal_id and not votes_revealed and status = 'in_review';
    perform set_config('app.revealing_votes', 'off', true);
  end if;
  return new;
end;
$$;

create trigger proposal_reviews_reveal
  after insert or update on proposal_reviews
  for each row execute function reveal_votes_when_complete();

-- Narrowing the voting body (all_members -> admins) can complete a vote
-- without anyone touching a review: reveal those proposals right away
create or replace function reveal_votes_after_mode_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform set_config('app.revealing_votes', 'on', true);
  update grant_proposals
  set votes_revealed = true
  where status = 'in_review' and not votes_revealed and proposal_votes_in(id);
  perform set_config('app.revealing_votes', 'off', true);
  return new;
end;
$$;

create trigger org_settings_grant_review_mode_reveal
  after update of grant_review_mode on org_settings
  for each row
  when (new.grant_review_mode is distinct from old.grant_review_mode)
  execute function reveal_votes_after_mode_change();

-- Proposal pipeline rules for signed-in users (the app's own transitions in
-- lib/actions/grants-out.ts):
--   anyone   received -> in_review (start review); received, in_review or
--            diligence -> withdrawn; create an internal proposal straight
--            in diligence (it skips review, so it starts revealed)
--   voters   everything else: advance to diligence, decide, decline at
--            review, and the decision fields. Voters are is_grant_voter():
--            every member, or only admins, per org_settings.grant_review_mode.
--            Making the award itself stays admin-only (grants_out policies).
-- votes_revealed is never set by hand, in either direction and at any
-- status: only the reveal above flips it. And a proposal enters review only
-- from 'received', so it can't be parked elsewhere and brought back.
create or replace function guard_proposal_changes()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.votes_revealed and new.status in ('received', 'in_review') then
      raise exception 'Votes are revealed automatically once every reviewer has voted or recused';
    end if;
    if new.status not in ('received', 'diligence') and not is_grant_voter() then
      raise exception 'Only grant reviewers can advance or decide grant proposals';
    end if;
    if (new.decision is not null or new.decision_date is not null or new.declined_stage is not null)
       and not is_grant_voter() then
      raise exception 'Only grant reviewers can advance or decide grant proposals';
    end if;
    return new;
  end if;

  if new.votes_revealed is distinct from old.votes_revealed
     and not (
       current_setting('app.revealing_votes', true) = 'on'
       and new.votes_revealed
       and old.status = 'in_review'
       and new.status = 'in_review'
       and proposal_votes_in(new.id)
     ) then
    raise exception 'Votes are revealed automatically once every reviewer has voted or recused, and can''t be changed by hand';
  end if;

  if new.status is distinct from old.status then
    if new.status = 'in_review' and old.status <> 'received' then
      raise exception 'Only new proposals can be moved into review';
    end if;
    if not is_grant_voter() and not (
      (old.status = 'received' and new.status = 'in_review')
      or (old.status in ('received', 'in_review', 'diligence') and new.status = 'withdrawn')
    ) then
      raise exception 'Only grant reviewers can advance or decide grant proposals';
    end if;
  end if;

  if not is_grant_voter()
     and (new.decision, new.decision_date, new.decision_notes, new.declined_stage)
         is distinct from (old.decision, old.decision_date, old.decision_notes, old.declined_stage) then
    raise exception 'Only grant reviewers can advance or decide grant proposals';
  end if;

  return new;
end;
$$;

create trigger grant_proposals_guard
  before insert or update on grant_proposals
  for each row execute function guard_proposal_changes();

-- Once the votes are revealed the reviews are the record: nobody can add,
-- change or delete one from a user session (deleting the whole proposal
-- still cascades)
create or replace function guard_revealed_reviews()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    return coalesce(new, old);
  end if;
  if exists (
    select 1 from grant_proposals p
    where p.votes_revealed
      and p.id in ((to_jsonb(new) ->> 'proposal_id')::uuid, (to_jsonb(old) ->> 'proposal_id')::uuid)
  ) then
    raise exception 'Votes on this proposal have been revealed, so reviews can no longer be changed';
  end if;
  return coalesce(new, old);
end;
$$;

create trigger proposal_reviews_frozen_after_reveal
  before insert or update or delete on proposal_reviews
  for each row execute function guard_revealed_reviews();

-- Awards and disbursements: money fields are admin-only ---------------------

-- The team can record the agreement date and the award's status; the
-- amount, the grantee and the proposal it came from are set by admins
-- (createAward / recordDecision)
create or replace function guard_award_changes()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or is_admin() then
    return new;
  end if;
  if (new.amount_awarded_cents, new.grantee_contact_id, new.proposal_id)
     is distinct from (old.amount_awarded_cents, old.grantee_contact_id, old.proposal_id) then
    raise exception 'Only admins can change an award''s amount or grantee';
  end if;
  return new;
end;
$$;

create trigger grants_out_money_guard
  before update on grants_out
  for each row execute function guard_award_changes();

-- The team can schedule a disbursement, edit a scheduled one's date and
-- method, and cancel it; paying it (markDisbursementPaid) and changing an
-- amount or payment date are admin actions. Only a scheduled disbursement
-- can become paid, for admins too (a cancelled one must be rescheduled first)
create or replace function guard_disbursement_changes()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    return new;
  end if;

  if tg_op = 'UPDATE' and new.status = 'paid' and old.status <> 'scheduled' and old.status <> 'paid' then
    raise exception 'Only a scheduled disbursement can be marked paid';
  end if;

  if is_admin() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'scheduled' or new.paid_date is not null then
      raise exception 'Only admins can record a disbursement as paid';
    end if;
    return new;
  end if;

  if (new.amount_cents, new.paid_date, new.grant_out_id)
     is distinct from (old.amount_cents, old.paid_date, old.grant_out_id) then
    raise exception 'Only admins can change a disbursement''s amount or payment';
  end if;
  if new.status is distinct from old.status
     and not (old.status = 'scheduled' and new.status = 'cancelled') then
    raise exception 'Only admins can record a disbursement as paid';
  end if;
  return new;
end;
$$;

create trigger disbursements_money_guard
  before insert or update on disbursements
  for each row execute function guard_disbursement_changes();

-- Program-related investments: funding gate ---------------------------------

create or replace function guard_pri_funding()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  threshold bigint;
  memo pri_memos%rowtype;
  memo_attachment uuid;
begin
  if not (old.status = 'committed' and new.status <> 'committed') then
    return new;
  end if;

  select pri_board_approval_threshold_cents into threshold from org_settings where id = 1;
  if threshold is not null and new.amount_cents >= threshold and new.board_approval_date is null then
    raise exception 'Board approval is required before funding this PRI';
  end if;

  select * into memo from pri_memos where pri_id = new.id;
  if memo.id is null
     or coalesce(btrim(memo.q_exempt_purpose), '') = ''
     or coalesce(btrim(memo.q_why_investment), '') = ''
     or coalesce(btrim(memo.q_income_not_significant), '') = ''
     or coalesce(btrim(memo.q_use_of_funds), '') = ''
     or coalesce(btrim(memo.q_key_terms), '') = ''
     or coalesce(btrim(memo.q_success_outcomes), '') = ''
     or coalesce(btrim(memo.q_risks), '') = ''
     or coalesce(btrim(memo.q_exit_plan), '') = ''
     or coalesce(btrim(memo.q_conflicts), '') = ''
     or coalesce(btrim(memo.q_monitoring), '') = '' then
    raise exception 'The mission-alignment memo must be complete before funding this PRI';
  end if;

  -- The generated memo PDF is filed as an attachment too; it isn't the
  -- executed instrument
  select attachment_id into memo_attachment from pri_memo_pdfs where pri_id = new.id;
  if not exists (
    select 1 from attachments a
    where a.entity_type = 'pri' and a.entity_id = new.id
      and a.id is distinct from memo_attachment
  ) then
    raise exception 'Attach the executed instrument before funding this PRI';
  end if;

  return new;
end;
$$;

create trigger pris_funding_gate
  before update of status on pris
  for each row execute function guard_pri_funding();

-- Contributions with a sent acknowledgement letter are frozen -------------

create or replace function guard_acknowledged_contribution()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  -- Bookkeeping fields that may still change after the letter is sent
  unlocked text[] := array['qbo_txn_type', 'qbo_txn_id', 'notes', 'updated_at'];
begin
  if not exists (
    select 1 from acknowledgement_letters
    where contribution_id = old.id and status = 'sent'
  ) then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    raise exception 'This contribution has a sent acknowledgement letter and can''t be deleted';
  end if;

  if (to_jsonb(new) - unlocked) is distinct from (to_jsonb(old) - unlocked) then
    raise exception 'This contribution has a sent acknowledgement letter and can no longer be edited';
  end if;
  return new;
end;
$$;

create trigger contributions_acknowledged_lock
  before update or delete on contributions
  for each row execute function guard_acknowledged_contribution();

-- A sent acknowledgement letter is final -----------------------------------

-- The contribution lock above keys off the letter's status, so a sent
-- letter can't be regenerated, edited, reset or deleted from a user session
-- (that would lift the lock and let the gift change under the donor's
-- receipt). The one change allowed is recording a resend of the same PDF
-- ("Resend" in the app): a later sent_at with its recipient and message id.
create or replace function guard_sent_letter()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  resend_fields text[] := array['sent_to_email', 'sent_at', 'resend_message_id', 'updated_at'];
begin
  if auth.uid() is null or old.status <> 'sent' then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' then
    raise exception 'This acknowledgement letter was sent and can''t be deleted';
  end if;
  if (to_jsonb(new) - resend_fields) is distinct from (to_jsonb(old) - resend_fields) then
    raise exception 'This acknowledgement letter was sent and can no longer be changed';
  end if;
  if (to_jsonb(new) - 'updated_at') is distinct from (to_jsonb(old) - 'updated_at')
     and not (new.sent_at is not null and (old.sent_at is null or new.sent_at > old.sent_at)) then
    raise exception 'This acknowledgement letter was sent and can no longer be changed';
  end if;
  return new;
end;
$$;

create trigger acknowledgement_letters_sent_lock
  before update or delete on acknowledgement_letters
  for each row execute function guard_sent_letter();

-- Authors and creators are whoever is signed in -----------------------------

-- Stamps the signed-in member into the column named by the trigger
-- argument on insert, and keeps it from being reassigned later. Service-
-- role writes (cron, public intake) set it explicitly or leave it null.
-- proposal_comments and ticket_comments don't need this: their policies
-- already require author_id = current_member_id().
create or replace function stamp_current_member()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  col text := tg_argv[0];
begin
  if auth.uid() is null then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new := jsonb_populate_record(new, jsonb_build_object(col, current_member_id()));
  elsif (to_jsonb(new) -> col) is distinct from (to_jsonb(old) -> col) then
    raise exception '%.% can''t be changed', tg_table_name, col;
  end if;
  return new;
end;
$$;

create trigger stamp_author before insert or update of author_id on notes
  for each row execute function stamp_current_member('author_id');
create trigger stamp_creator before insert or update of created_by on tickets
  for each row execute function stamp_current_member('created_by');
create trigger stamp_creator before insert or update of created_by on meetings
  for each row execute function stamp_current_member('created_by');
create trigger stamp_creator before insert or update of created_by on note_intakes
  for each row execute function stamp_current_member('created_by');
create trigger stamp_creator before insert or update of created_by on contacts
  for each row execute function stamp_current_member('created_by');

-- Notes-inbox files live under their intake's folder ----------------------

-- Storage access to note files is decided by the folder ({intake_id}/...),
-- so a file row can't claim an object from someone else's intake
alter table note_intake_files
  add constraint note_intake_files_in_intake_folder
  check (split_part(storage_path, '/', 1) = intake_id::text);

-- Note attachments must come from the uploader's own notes-inbox files ------

create or replace function guard_note_attachment_path()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    return new;
  end if;
  if not exists (
    select 1
    from note_intake_files f
    join note_intakes i on i.id = f.intake_id
    where f.storage_path = new.storage_path
      and (i.created_by = current_member_id() or is_admin())
  ) then
    raise exception 'Attachments must be files from your own notes inbox';
  end if;
  return new;
end;
$$;

create trigger note_attachments_path_guard
  before insert or update of storage_path on note_attachments
  for each row execute function guard_note_attachment_path();

